// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(c.blacklist(actor) == false);

        // initialize distribution state via the entry point
        c.XBornID();

        // value handed out on the first distribution call
        uint256 v = c.value();
        vm.assume(v <= c.totalRemaining());

        vm.prank(actor);
        c.getTokens();

        // GENERAL RULE: a successful distribution credits the recipient's
        // balance by exactly the amount distributed.
        assertTrue(c.balanceOf(actor) == v);
    }
}
